{
  "name": "@playwright/mcp",
  "version": "0.0.83",
  "description": "Playwright Tools for MCP",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/microsoft/playwright-mcp.git"
  },
  "homepage": "https://playwright.dev",
  "engines": {
    "node": ">=18"
  },
  "author": {
    "name": "Microsoft Corporation"
  },
  "license": "Apache-2.0",
  "mcpName": "io.github.microsoft/playwright-mcp",
  "scripts": {
    "lint": "node update-readme.js",
    "test": "playwright test",
    "ctest": "playwright test --project=chrome",
    "ftest": "playwright test --project=firefox",
    "wtest": "playwright test --project=webkit",
    "dtest": "MCP_IN_DOCKER=1 playwright test --project=chromium-docker",
    "build": "echo OK",
    "npm-publish": "npm run lint && npm run test && npm publish",
    "docker-build": "docker build --no-cache -t playwright-mcp-dev:latest .",
    "docker-rm": "docker rm playwright-mcp-dev",
    "docker-run": "docker run -it -p 8080:8080 --name playwright-mcp-dev playwright-mcp-dev:latest",
    "roll": "node roll.js"
  },
  "exports": {
    "./package.json": "./package.json",
    ".": {
      "types": "./index.d.ts",
      "default": "./index.js"
    }
  },
  "dependencies": {
    "playwright": "1.64.0-alpha-1790635538000",
    "playwright-core": "1.64.0-alpha-1790635538000"
  },
  "devDependencies": {
    "@modelcontextprotocol/sdk": "^1.25.2",
    "@playwright/test": "1.64.0-alpha-1790635538000",
    "@types/node": "^24.3.0"
  },
  "bin": {
    "playwright-mcp": "cli.js"
  }
}

{
  "$schema": "https://static.modelcontextprotocol.io/schemas/2025-12-11/server.schema.json",
  "name": "io.github.microsoft/playwright-mcp",
  "description": "Playwright Tools for MCP",
  "repository": {
    "url": "https://github.com/microsoft/playwright-mcp",
    "source": "github"
  },
  "version": "0.0.83",
  "packages": [
    {
      "registryType": "npm",
      "identifier": "@playwright/mcp",
      "version": "0.0.83",
      "transport": {
        "type": "stdio"
      }
    }
  ]
}

{
  "$schema": "https://static.modelcontextprotocol.io/schemas/2025-12-11/server.schema.json",
  "name": "io.github.github/github-mcp-server",
  "description": "Connect AI assistants to GitHub - manage repos, issues, PRs, and workflows through natural language.",
  "title": "GitHub",
  "repository": {
    "url": "https://github.com/github/github-mcp-server",
    "source": "github"
  },
  "version": "${VERSION}",
  "packages": [
    {
      "registryType": "oci",
      "identifier": "ghcr.io/github/github-mcp-server:${VERSION}",
      "transport": {
        "type": "stdio"
      },
      "runtimeArguments": [
        {
          "type": "named",
          "name": "-p",
          "description": "Publish the OAuth callback port to loopback so the in-container login callback is reachable",
          "value": "127.0.0.1:8085:8085"
        },
        {
          "type": "named",
          "name": "-e",
          "description": "Fixed OAuth callback port, matching the published port above",
          "value": "GITHUB_OAUTH_CALLBACK_PORT=8085"
        },
        {
          "type": "named",
          "name": "-e",
          "description": "Optional GitHub Personal Access Token. Omit to log in with OAuth on first use.",
          "value": "GITHUB_PERSONAL_ACCESS_TOKEN={token}",
          "isRequired": false,
          "variables": {
            "token": {
              "isRequired": false,
              "isSecret": true,
              "format": "string"
            }
          }
        }
      ]
    }
  ],
  "remotes": [
    {
      "type": "streamable-http",
      "url": "https://api.githubcopilot.com/mcp/",
      "headers": [
        {
          "name": "Authorization",
          "description": "Authorization header with authentication token (PAT or App token)",
          "isSecret": true
        }
      ]
    }
  ]
}

{
	"name": "github",
	"version": "1.0.0",
	"mcpServers": {
		"github": {
			"description": "Connect AI assistants to GitHub - manage repos, issues, PRs, and workflows through natural language.",
			"httpUrl": "https://api.githubcopilot.com/mcp/",
			"headers": {
				"Authorization": "Bearer $GITHUB_MCP_PAT"
			}
		}
	}
}

{
  "$schema": "https://agent-plugins.org/schemas/1.0.0/mcp.schema.json",
  "mcpServers": {
    "chrome-devtools": {
      "type": "stdio",
      "command": "npx",
      "args": [
        "--prefix",
        "${PLUGIN_DATA}",
        "chrome-devtools-mcp@1.11.0"
      ]
    }
  }
}
